/// The packed (newline separated, no namespace) list of [registry], or null.
String? vanillaRegistryPacked(String registry) {
  switch (registry) {
    case 'minecraft:item':
      return vanillaItemPacked;
    case 'minecraft:block':
      return vanillaBlockPacked;
    case 'minecraft:entity_type':
      return vanillaEntityTypePacked;
    case 'minecraft:fluid':
      return vanillaFluidPacked;
    case 'minecraft:mob_effect':
      return vanillaMobEffectPacked;
    case 'minecraft:potion':
      return vanillaPotionPacked;
    case 'minecraft:attribute':
      return vanillaAttributePacked;
    case 'minecraft:data_component_type':
      return vanillaDataComponentTypePacked;
    case 'minecraft:particle_type':
      return vanillaParticleTypePacked;
    case 'minecraft:sound_event':
      return vanillaSoundEventPacked;
    case 'minecraft:game_event':
      return vanillaGameEventPacked;
    case 'minecraft:custom_stat':
      return vanillaCustomStatPacked;
    case 'minecraft:menu':
      return vanillaMenuPacked;
    case 'minecraft:block_entity_type':
      return vanillaBlockEntityTypePacked;
    default:
      return null;
  }
}
